/**
 * Unit suite for @ohos/dsh-credentials-live: staged-key reconciliation.
 *
 * The reconciliation core (readStagedKey / syncOnce) is exercised against a
 * fake credentials service; the apply() test drives the live watcher loop
 * with a short interval, then asserts disposal stops both paths.
 *
 * Run from the payload tree so @deepseek-ai/* imports resolve (§8 recipe).
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, rmSync, writeFileSync, unlinkSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { Config, apply, readStagedKey, syncOnce } from '../index.js'

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

/** Fake credentials service: records calls, `env` simulates the frozen boot env. */
function fakeCredentials(env = {}) {
	const calls = []
	const store = new Map()
	return {
		calls,
		async set(ref, value) {
			calls.push(['set', ref, value])
			store.set(ref, value)
		},
		async unset(ref) {
			calls.push(['unset', ref])
			store.delete(ref)
		},
		resolve(ref) {
			if (store.has(ref)) return Promise.resolve({ value: store.get(ref), source: 'file' })
			if (env[ref] !== undefined) return Promise.resolve({ value: env[ref], source: 'env' })
			return Promise.resolve(undefined)
		}
	}
}

/** A temp key file plus its directory; removed on test end by the caller. */
function stageKeyFile(initial) {
	const dir = mkdtempSync(join(tmpdir(), 'credentials-live-'))
	const keyFile = join(dir, '.api-key')
	if (initial !== undefined) writeFileSync(keyFile, initial)
	return { dir, keyFile }
}

const cleanup = (dir) => rmSync(dir, { recursive: true, force: true })

test('readStagedKey trims and treats a missing file as empty', async () => {
	const { dir, keyFile } = stageKeyFile('sk-test\n')
	try {
		assert.equal(await readStagedKey(keyFile), 'sk-test')
		unlinkSync(keyFile)
		assert.equal(await readStagedKey(keyFile), '')
	} finally {
		cleanup(dir)
	}
})

test('syncOnce writes a changed key through set', async () => {
	const { dir, keyFile } = stageKeyFile('sk-new')
	try {
		const credentials = fakeCredentials({ DEEPSEEK_API_KEY: 'sk-old' })
		const seen = { value: undefined }
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'set')
		assert.deepEqual(credentials.calls, [['set', 'DEEPSEEK_API_KEY', 'sk-new']])
		assert.equal(seen.value, 'sk-new')
	} finally {
		cleanup(dir)
	}
})

test('syncOnce adopts an equal value without writing', async () => {
	const { dir, keyFile } = stageKeyFile('sk-old')
	try {
		const credentials = fakeCredentials({ DEEPSEEK_API_KEY: 'sk-old' })
		const seen = { value: undefined }
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'adopt')
		assert.deepEqual(credentials.calls, [])
		assert.equal(seen.value, 'sk-old')
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'same')
	} finally {
		cleanup(dir)
	}
})

test('syncOnce clears the store when the staged key is removed', async () => {
	const { dir, keyFile } = stageKeyFile()
	try {
		const credentials = fakeCredentials({ DEEPSEEK_API_KEY: 'sk-old' })
		const seen = { value: 'sk-old' }
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'unset')
		assert.deepEqual(credentials.calls, [['unset', 'DEEPSEEK_API_KEY']])
		assert.equal(seen.value, '')
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'same')
	} finally {
		cleanup(dir)
	}
})

test('syncOnce stays silent when boot has no key anywhere', async () => {
	const { dir, keyFile } = stageKeyFile()
	try {
		const credentials = fakeCredentials()
		const seen = { value: undefined }
		assert.equal(await syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), 'adopt')
		assert.deepEqual(credentials.calls, [])
	} finally {
		cleanup(dir)
	}
})

test('syncOnce leaves seen untouched when the store write fails', async () => {
	const { dir, keyFile } = stageKeyFile('sk-new')
	try {
		const credentials = fakeCredentials()
		credentials.set = async () => {
			throw new Error('store down')
		}
		const seen = { value: undefined }
		await assert.rejects(syncOnce(credentials, keyFile, 'DEEPSEEK_API_KEY', seen), /store down/)
		assert.equal(seen.value, undefined)
	} finally {
		cleanup(dir)
	}
})

test('syncOnce propagates non-ENOENT read errors', async () => {
	const { dir, keyFile } = stageKeyFile()
	try {
		const credentials = fakeCredentials()
		const seen = { value: undefined }
		// reading a directory fails with EISDIR, not ENOENT
		await assert.rejects(syncOnce(credentials, dir, 'DEEPSEEK_API_KEY', seen))
		assert.equal(seen.value, undefined)
	} finally {
		cleanup(dir)
	}
})

test('apply hot-updates on change and disposes cleanly', async () => {
	const { dir, keyFile } = stageKeyFile('sk-first')
	try {
		const credentials = fakeCredentials()
		const disposers = []
		const ctx = {
			credentials,
			effect(fn) {
				disposers.push(fn())
				return () => {}
			}
		}
		const config = Config({ intervalMs: 20, keyFile, envName: 'DEEPSEEK_API_KEY' })
		apply(ctx, config)
		await sleep(120)
		assert.deepEqual(credentials.calls, [['set', 'DEEPSEEK_API_KEY', 'sk-first']])
		writeFileSync(keyFile, 'sk-second')
		await sleep(120)
		assert.deepEqual(credentials.calls, [
			['set', 'DEEPSEEK_API_KEY', 'sk-first'],
			['set', 'DEEPSEEK_API_KEY', 'sk-second']
		])
		assert.equal(disposers.length, 1)
		disposers[0]()
		writeFileSync(keyFile, 'sk-third')
		await sleep(150)
		assert.equal(credentials.calls.length, 2)
	} finally {
		cleanup(dir)
	}
})
